// Nodo "Armar pedido a Claude" — productos todavía sin normalizar → un pedido a la API.
const prods = $input.all().map((i) => i.json).filter((p) => p && p.ean);
if (!prods.length) return [];

const sistema = `Sos un analista de datos maestros de PepsiCo Argentina (snacks).
Recibís productos con su EAN y el nombre tal como aparece en un supermercado online.
Para cada uno devolvé:
- nombre_corto: nombre limpio y consistente, formato "<Marca> <Variedad> <gramaje>g" (ej. "Lay's Clásicas 85g", "Doritos Queso 129g", "Pehuamar Maní Salado 120g").
- marca: una de Lay's, Doritos, 3D, Cheetos, Tostitos, Twistos, Pehuamar (u "Otra" si no corresponde).
- variedad: sabor o línea (ej. "Clásicas", "Jamón Serrano", "Queso", "Dinamita Flamin' Hot", "Rústicas Sal Marina").
- segmento: uno de "Papas fritas", "Nachos", "Snacks de maíz", "Palitos y conitos", "Maní", "Galletitas/Tostadas", "Otros".
- gramaje_g: número en gramos (null si no se puede saber).
No inventes datos que no surjan del nombre. Respondé SOLO un array JSON, sin texto antes ni después.`;

const lista = prods.map((p) => `${p.ean} | ${p.marca || ''} | ${p.nombre || ''}`).join('\n');

return [{ json: {
  cantidad: prods.length,
  body: {
    model: 'claude-haiku-5-5',
    max_tokens: 8000,
    system: sistema,
    messages: [{ role: 'user', content: `Productos (EAN | marca | nombre):\n${lista}\n\nDevolvé el array JSON con objetos {ean, nombre_corto, marca, variedad, segmento, gramaje_g}.` }],
  },
} }];

// Nodo "Leer respuesta de Claude" — extrae el JSON y lo valida antes de guardarlo.
const res = $input.first().json;
const texto = (res.content || []).filter((c) => c.type === 'text').map((c) => c.text).join('');
const ini = texto.indexOf('[');
const fin = texto.lastIndexOf(']');
if (ini < 0 || fin < ini) throw new Error('Claude no devolvió un array JSON: ' + texto.slice(0, 300));

let arr;
try { arr = JSON.parse(texto.slice(ini, fin + 1)); } catch (e) { throw new Error('JSON inválido de Claude: ' + e.message); }

const MARCAS = ["Lay's", 'Doritos', '3D', 'Cheetos', 'Tostitos', 'Twistos', 'Pehuamar', 'Otra'];
const limpio = (s, max = 120) => (typeof s === 'string' ? s.trim().slice(0, max) : null);
const filas = (Array.isArray(arr) ? arr : [])
  .filter((x) => x && x.ean)
  .map((x) => ({
    ean: String(x.ean).trim(),
    nombre_corto: limpio(x.nombre_corto),
    marca: MARCAS.includes(x.marca) ? x.marca : null,
    variedad: limpio(x.variedad, 60),
    segmento: limpio(x.segmento, 40),
    gramaje_g: Number.isFinite(Number(x.gramaje_g)) && Number(x.gramaje_g) > 0 ? Number(x.gramaje_g) : null,
  }));

return [{ json: { filas: JSON.stringify(filas), cantidad: filas.length } }];
